// Auto-refresh when entering the screen
// Ensure date pickers have defaults; then compute


// Screen_Stats.OnVisible
UpdateContext({ varResetDp: true });

// Optionally calculate your default dates too:
UpdateContext(
    {
    locStartDefault: Date(Year(Today()), Month(Today()) -2, 1), // see note below
    locEndDefault: Today()
});

// Immediately drop the flag back to false after the reset tick
// (use a single UpdateContext call with both if you prefer; the important bit is the reset transition)
UpdateContext({ varResetDp: false });



// === Compute Stats for Screen_Stats ===
// Resolve the date range from pickers, with safety defaults
UpdateContext(
    {
        locStart: If(
            IsBlank(dpStart_Stats.SelectedDate),
            Date(Year(Today()), Month(Today()) - 2, 1),
            dpStart_Stats.SelectedDate
        ),
        locEnd: If(
            IsBlank(dpEnd_Stats.SelectedDate),
            Today(),
            dpEnd_Stats.SelectedDate
        )
    }
);

// Pull base rows within date range
// NOTE: If FeedbackDate is SharePoint Date/Time, this remains delegable.
ClearCollect(
    colRows_Stats,
    Filter(VIR_RealTime_FeedBack, EvalDate >= locStart And EvalDate < DateAdd(locEnd, 1, TimeUnit.Days))
);

// Normalize month fields for trend charts
ClearCollect(
    colRowsWithMonth_Stats,
    AddColumns(
        colRows_Stats,
        MonthKey,   Date( Year(EvalDate), Month(EvalDate), 1 ),
        MonthLabel, Text( Date( Year(EvalDate), Month(EvalDate), 1 ), "yyyy-mmm" )
    )
);

// === 1) Counts by Attending ===
ClearCollect(
    colByAttending_Stats,
    AddColumns(
        GroupBy(colRowsWithMonth_Stats, Attending, grp),
        Count, CountRows(grp)
    )
);
ClearCollect(
    colByAttending_Sorted_Stats,
    SortByColumns(colByAttending_Stats, "Count", SortOrder.Descending)
);
Set(varTotalByAttending_Stats, Sum(colByAttending_Stats, Count));

// === 2) Counts by ProcedureName (text) ===
ClearCollect(
    colByProcedure_Stats,
    AddColumns(
        GroupBy(colRowsWithMonth_Stats, ProcedureName, grp),
        Count, CountRows(grp)
    )
);
ClearCollect(
    colByProcedure_Sorted_Stats,
    SortByColumns(colByProcedure_Stats, "Count", SortOrder.Descending)
);
Set(varTotalByProcedure_Stats, Sum(colByProcedure_Stats, Count));

// === 3) Counts by Resident (received) ===
ClearCollect(
    colByResident_Stats,
    AddColumns(
        GroupBy(colRowsWithMonth_Stats, ResidentName, grp),
        Count, CountRows(grp)
    )
);
ClearCollect(
    colByResident_Sorted_Stats,
    SortByColumns(colByResident_Stats, "Count", SortOrder.Descending)
);
Set(varTotalByResident_Stats, Sum(colByResident_Stats, Count));

// === 4) Month scaffolding for line charts (no gaps) ===
ClearCollect(
    colMonths_Stats,
    AddColumns(
        Sequence(
            DateDiff(
                Date( Year(locStart), Month(locStart), 1 ),
                Date( Year(locEnd),   Month(locEnd),   1 ),
                TimeUnit.Months
            ) + 1
        ),
        MonthKey, DateAdd( Date( Year(locStart), Month(locStart), 1 ), Value - 1, TimeUnit.Months ),
        MonthLabel, Text( DateAdd( Date( Year(locStart), Month(locStart), 1 ), Value - 1, TimeUnit.Months ), "yyyy-mmm" )
    )
);

// === 5) Pre-aggregate monthly counts for Attending and Resident (for trend drilldowns) ===
ClearCollect(
    colMonthlyByAttending_Stats,
    AddColumns(
        GroupBy(colRowsWithMonth_Stats, Attending, MonthKey, MonthLabel, grp),
        Count, CountRows(grp)
    )
);
ClearCollect(
    colMonthlyByResident_Stats,
    AddColumns(
        GroupBy(colRowsWithMonth_Stats, ResidentName, MonthKey, MonthLabel, grp),
        Count, CountRows(grp)
    )
);

// (Optional) initialize dropdown defaults
If( CountRows(colByAttending_Sorted_Stats) > 0,
    Set(varSelAttending_Stats, First(colByAttending_Sorted_Stats).Attending)
);
If( CountRows(colByResident_Sorted_Stats) > 0,
    Set(varSelResident_Stats, First(colByResident_Sorted_Stats).ResidentName)
);


// Build a chart-ready table: ProcedureName | Count | Percent (0–1) | Metric (default Count)
ClearCollect(
    colByProcedure_ForChart,
    AddColumns(
        Filter(colByProcedure_Stats, !IsBlank(ProcedureName)),
        Percent, If(varTotalByProcedure_Stats > 0, Count / varTotalByProcedure_Stats, 0),
        Metric, Count    // default metric is Count; we’ll override via a toggle
    )
);

// A sorted version for Top-N filtering & nicer chart order
ClearCollect(
    colByProcedure_ForChart_Sorted,
    SortByColumns(colByProcedure_ForChart, "Count", SortOrder.Descending)
);

